    def click_button(self, btn:str):
        '''
        Click a button whose name should be in the keys of _buttons.
        '''
        _buttons = {"OK":BillingSecurityObjects.oK_Button, "Cancel":BillingSecurityObjects.cancel_Button, "Edit List":BillingSecurityObjects.ledgers_Edit_List_Button,
                    "Information_OK" : {"container": {"text":"Information", "type": "Window"}, "text": "OK", "type": "Button"} }
        if btn in _buttons:
            CommonActions.left_click_object(_buttons[btn])

    def select_tab(self, tab: str):
        '''
        Select a tab by click a location of tab's title, x of the relative coordinate is given as the value of the dict item

        where key is the name of the tab, and y is fixed to 10.
        '''
        tab_x = {"General":20, "Configuration & Reports":120, "Ledgers":230}
        y = 10
        if tab in tab_x:
            CommonActions.mouse_click_with_relative_x_and_y_offsets(BillingSecurityObjects.billing_Security_Pane, tab_x[tab], y)